package com.camjewell.tobpointtracker;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Which team points the unique chance is worked out from during a raid. Both agree once Verzik is dead.
 */
@Getter
@RequiredArgsConstructor
public enum ChanceBasis
{
	/**
	 * Starts at the full rate and only drops on deaths, assuming the rest of the raid is cleared without dying.
	 */
	PROJECTED("Projected"),
	/**
	 * Starts at 0 and climbs as points are earned, like the CoX and ToA trackers.
	 */
	CURRENT("Current");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.camjewell.tobpointtracker;

/**
 * What can be proven about whether a player earned a segment's MVP points.
 */
public enum MvpOutcome
{
	WON,
	LOST,
	/**
	 * Teammates without the plugin might have out-damaged them, or might not.
	 */
	UNKNOWN
}

package com.camjewell.tobpointtracker;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Applies the Theatre of Blood points formula (as modelled by the OSRS Wiki loot calculator):
 * <ul>
 *     <li>Every player earns 3 points per room completed (18 max).</li>
 *     <li>14 MVP points are split per segment to whoever dealt the most damage to the boss.</li>
 *     <li>Every death costs the dying player 4 points. A player can't go below 0.</li>
 *     <li>Team max is {@code 18 * teamSize + 14}, so a solo raid maxes at 32 and a 5-man at 104.</li>
 *     <li>Team unique chance = base rate (1/9.1 normal, 1/7.7 hard, none in entry) * team points / team max.</li>
 *     <li>If a unique is rolled, each player's chance of receiving it is their points / team points.</li>
 * </ul>
 */
public final class PointCalculator
{
	private PointCalculator()
	{
	}

	@Value
	public static class PlayerScore
	{
		String name;
		boolean local;
		int roomPoints;
		int deaths;
		/**
		 * MVP points the player has provably earned.
		 */
		int mvpWon;
		/**
		 * MVP points the player might have earned, which can't be proven either way without every teammate's damage.
		 */
		int mvpUnknown;
		/**
		 * Whether we have this player's damage, which is only true for us and RuneLite party members running the plugin.
		 */
		boolean damageKnown;
		/**
		 * The MVP outcome of each completed segment, indexed by {@link Segment} ordinal (null if not yet completed).
		 */
		MvpOutcome[] outcomes;
		int minPoints;
		int maxPoints;
		/**
		 * The player's chance of personally receiving a unique (team chance times their share of the team's points),
		 * assuming they lost / won every MVP that can't be proven.
		 */
		double minUniqueChance;
		double maxUniqueChance;

		public boolean isExact()
		{
			return minPoints == maxPoints;
		}
	}

	@Value
	public static class RaidScore
	{
		RaidMode mode;
		int teamSize;
		int teamPoints;
		int maxPoints;
		/**
		 * Team points at the end of the raid if every remaining room is cleared without another death.
		 */
		int projectedTeamPoints;
		int totalDeaths;
		/**
		 * Team chance of a unique, based on {@link #projectedTeamPoints} or {@link #teamPoints} depending on the
		 * {@link ChanceBasis}.
		 */
		double teamUniqueChance;
		boolean complete;
		List<PlayerScore> players;
	}

	public static int maxTeamPoints(int teamSize)
	{
		return Segment.ROOM_COUNT * Segment.POINTS_PER_ROOM * teamSize + Segment.TOTAL_MVP_POINTS;
	}

	public static double teamUniqueChance(RaidMode mode, int teamPoints, int teamSize)
	{
		return mode.getBaseUniqueChance() * Math.max(0, teamPoints) / maxTeamPoints(teamSize);
	}

	public static RaidScore calculate(RaidState raid)
	{
		return calculate(raid, ChanceBasis.PROJECTED);
	}

	public static RaidScore calculate(RaidState raid, ChanceBasis basis)
	{
		final int teamSize = raid.getTeamSize();
		final Map<String, String> team = raid.getTeam();
		final List<String> keys = new ArrayList<>(team.keySet());

		MvpOutcome[][] outcomes = new MvpOutcome[keys.size()][Segment.count()];
		int awardedMvp = 0;
		for (Segment segment : raid.getCompleted())
		{
			awardedMvp += segment.getMvpPoints();
			MvpOutcome[] segmentOutcomes = mvpOutcomes(raid, keys, segment);
			for (int i = 0; i < keys.size(); i++)
			{
				outcomes[i][segment.ordinal()] = segmentOutcomes[i];
			}
		}

		final int totalDeaths = raid.getTotalDeaths();
		final int roomPoints = raid.getRoomsCompleted() * Segment.POINTS_PER_ROOM;
		final int teamPoints = Math.max(0, roomPoints * teamSize + awardedMvp - totalDeaths * Segment.DEATH_PENALTY);
		final int maxPoints = maxTeamPoints(teamSize);
		final int projected = Math.max(0, maxPoints - totalDeaths * Segment.DEATH_PENALTY);
		final double teamChance = teamUniqueChance(raid.getMode(),
			basis == ChanceBasis.CURRENT ? teamPoints : projected, teamSize);

		List<PlayerScore> players = new ArrayList<>(keys.size());
		for (int i = 0; i < keys.size(); i++)
		{
			String key = keys.get(i);
			int won = 0;
			int unknown = 0;
			for (Segment segment : raid.getCompleted())
			{
				MvpOutcome outcome = outcomes[i][segment.ordinal()];
				if (outcome == MvpOutcome.WON)
				{
					won += segment.getMvpPoints();
				}
				else if (outcome == MvpOutcome.UNKNOWN)
				{
					unknown += segment.getMvpPoints();
				}
			}

			int deaths = raid.getDeaths(key);
			int base = roomPoints - deaths * Segment.DEATH_PENALTY;
			int min = Math.max(0, base + won);
			int max = Math.max(0, base + won + unknown);
			players.add(new PlayerScore(
				team.get(key),
				key.equals(raid.getLocalName()),
				roomPoints,
				deaths,
				won,
				unknown,
				raid.getDamage().containsKey(key),
				outcomes[i],
				min,
				max,
				teamChance * share(min, teamPoints, keys.size()),
				teamChance * share(max, teamPoints, keys.size())));
		}

		return new RaidScore(raid.getMode(), teamSize, teamPoints, maxPoints, projected, totalDeaths, teamChance,
			raid.isComplete(), players);
	}

	/**
	 * Fraction of the team's points a player holds, i.e. the chance a rolled unique goes to them. Before anyone has
	 * earned points, everyone has an even share.
	 */
	private static double share(int points, int teamPoints, int players)
	{
		return teamPoints > 0 ? Math.min(1, (double) points / teamPoints) : 1.0 / Math.max(1, players);
	}

	/**
	 * Works out what can be proven about each player's MVP for a segment, without guessing how damage we can't
	 * attribute was split between teammates who aren't sharing it.
	 * <p>
	 * For a player whose damage {@code d} we know, with {@code k} teammates not sharing data who between them dealt
	 * {@code u} damage that we saw but can't attribute:
	 * <ul>
	 *     <li>WON if {@code d} beats every other known player, and beats {@code u} (since any one of them dealt at most
	 *     {@code u}).</li>
	 *     <li>LOST if another known player dealt more, or {@code u > k * d} (so at least one of them must have dealt
	 *     more than {@code d}).</li>
	 *     <li>Otherwise UNKNOWN. Exact ties are also UNKNOWN, as we don't know how the game breaks them.</li>
	 * </ul>
	 * A player without data is LOST if someone else provably WON, and otherwise UNKNOWN.
	 */
	static MvpOutcome[] mvpOutcomes(RaidState raid, List<String> keys, Segment segment)
	{
		final int n = keys.size();
		int[] dmg = new int[n];
		boolean[] known = new boolean[n];
		int knownTotal = 0;
		int unknownPlayers = 0;
		for (int i = 0; i < n; i++)
		{
			int[] d = raid.getDamage().get(keys.get(i));
			if (d == null)
			{
				unknownPlayers++;
				continue;
			}
			known[i] = true;
			dmg[i] = d[segment.ordinal()];
			knownTotal += dmg[i];
		}
		final int unattributed = Math.max(0, raid.getTotalDamage()[segment.ordinal()] - knownTotal);

		MvpOutcome[] result = new MvpOutcome[n];
		boolean anyoneWon = false;
		for (int i = 0; i < n; i++)
		{
			if (!known[i])
			{
				continue;
			}

			boolean beaten = false;
			boolean tied = false;
			for (int j = 0; j < n; j++)
			{
				if (j != i && known[j])
				{
					beaten |= dmg[j] > dmg[i];
					tied |= dmg[j] == dmg[i];
				}
			}

			if (beaten || (unknownPlayers > 0 && unattributed > (long) unknownPlayers * dmg[i]))
			{
				result[i] = MvpOutcome.LOST;
			}
			else if (!tied && dmg[i] > 0 && (unknownPlayers == 0 || dmg[i] > unattributed))
			{
				result[i] = MvpOutcome.WON;
				anyoneWon = true;
			}
			else
			{
				result[i] = MvpOutcome.UNKNOWN;
			}
		}

		for (int i = 0; i < n; i++)
		{
			if (!known[i])
			{
				result[i] = anyoneWon ? MvpOutcome.LOST : MvpOutcome.UNKNOWN;
			}
		}
		return result;
	}
}

package com.camjewell.tobpointtracker;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum RaidMode
{
	// Entry Mode can't roll uniques at all; points are still tracked for practice.
	ENTRY("Entry", 0),
	NORMAL("Normal", 1 / 9.1),
	HARD("Hard", 1 / 7.7);

	private final String displayName;
	/**
	 * Team unique chance for a perfect (max points) raid.
	 */
	private final double baseUniqueChance;

	public boolean canRollUniques()
	{
		return baseUniqueChance > 0;
	}

	static RaidMode fromChatName(String name)
	{
		switch (name.toLowerCase())
		{
			case "entry":
			case "story":
				return ENTRY;
			case "hard":
				return HARD;
			default:
				return NORMAL;
		}
	}
}

package com.camjewell.tobpointtracker;

import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import lombok.Setter;

/**
 * Everything observed about the current raid. Player names are keyed by their standardized form (see
 * {@link net.runelite.client.util.Text#standardize}) and the display form is kept for rendering.
 */
@Getter
public class RaidState
{
	public static final int MAX_TEAM_SIZE = 5;

	// standardized name -> display name, in party slot order
	private final Map<String, String> team = new LinkedHashMap<>();
	private final EnumSet<Segment> completed = EnumSet.noneOf(Segment.class);
	private final Map<String, Integer> deaths = new HashMap<>();
	// "room:name" keys, since a dead player spectates for the rest of the room and can't die twice in it
	private final Set<String> deathKeys = new HashSet<>();
	// Players currently dead. Death sources can report the same death several ticks apart (the party orbs lag behind
	// ActorDeath), sometimes after the room has ended, so a player can't die again until they've been seen alive.
	private final Set<String> deadPlayers = new HashSet<>();
	// Damage per segment that we know is attributed to a player: ours from our own hitsplats, others from party updates
	private final Map<String, int[]> damage = new HashMap<>();
	// All boss damage hitsplats we saw, regardless of who dealt them
	private final int[] totalDamage = new int[Segment.count()];

	private final String localName;

	@Setter
	private RaidMode mode = RaidMode.NORMAL;
	@Setter
	private boolean modeKnown;

	public RaidState(String localName)
	{
		this.localName = localName;
		damage.put(localName, new int[Segment.count()]);
	}

	public void addTeamMember(String key, String displayName)
	{
		if (team.size() < MAX_TEAM_SIZE || team.containsKey(key))
		{
			team.putIfAbsent(key, displayName);
		}
	}

	public int getTeamSize()
	{
		return Math.max(1, team.size());
	}

	/**
	 * The room currently being fought, or {@link Segment#ROOM_COUNT} once Verzik is dead.
	 */
	public int getCurrentRoom()
	{
		for (Segment s : Segment.values())
		{
			if (!completed.contains(s))
			{
				return s.getRoom();
			}
		}
		return Segment.ROOM_COUNT;
	}

	public Segment getCurrentSegment()
	{
		for (Segment s : Segment.values())
		{
			if (!completed.contains(s))
			{
				return s;
			}
		}
		return null;
	}

	public int getRoomsCompleted()
	{
		int rooms = 0;
		for (Segment s : completed)
		{
			if (s.endsRoom())
			{
				rooms++;
			}
		}
		return rooms;
	}

	public boolean isComplete()
	{
		return completed.contains(Segment.VERZIK_P3);
	}

	/**
	 * Marks a segment and every segment before it as complete, since the raid is linear and an event for an earlier
	 * segment may have been missed (e.g. the boss died while we were loading).
	 *
	 * @return whether anything changed
	 */
	public boolean completeThrough(Segment segment)
	{
		boolean changed = false;
		for (Segment s : Segment.values())
		{
			if (s.ordinal() > segment.ordinal())
			{
				break;
			}
			changed |= completed.add(s);
		}
		return changed;
	}

	/**
	 * @return whether this was a new death (the player wasn't already dead, and hasn't died in the current room)
	 */
	public boolean recordDeath(String key)
	{
		if (isComplete() || !team.containsKey(key) || deadPlayers.contains(key)
			|| !deathKeys.add(getCurrentRoom() + ":" + key))
		{
			return false;
		}
		deadPlayers.add(key);
		deaths.merge(key, 1, Integer::sum);
		return true;
	}

	/**
	 * Marks a dead player as alive again, once they've respawned for the next room.
	 */
	public void markAlive(String key)
	{
		deadPlayers.remove(key);
	}

	public int getDeaths(String key)
	{
		return deaths.getOrDefault(key, 0);
	}

	public int getTotalDeaths()
	{
		int total = 0;
		for (String key : team.keySet())
		{
			total += getDeaths(key);
		}
		return total;
	}

	public void recordHit(Segment segment, int amount, boolean mine)
	{
		totalDamage[segment.ordinal()] += amount;
		if (mine)
		{
			damage.get(localName)[segment.ordinal()] += amount;
		}
	}

	public int[] getLocalDamage()
	{
		return damage.get(localName);
	}

	public void setPartyDamage(String key, int[] segmentDamage)
	{
		if (!key.equals(localName) && segmentDamage != null && segmentDamage.length == Segment.count())
		{
			damage.put(key, segmentDamage.clone());
		}
	}

	public void clearPartyDamage()
	{
		damage.keySet().removeIf(key -> !key.equals(localName));
	}

	public Map<String, int[]> getDamage()
	{
		return Collections.unmodifiableMap(damage);
	}
}

package com.camjewell.tobpointtracker;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * A scoring segment of the raid. Each room awards {@link #POINTS_PER_ROOM} to every player, and each segment awards its
 * MVP points to whoever dealt the most damage to the boss during it. Verzik is one room split into three MVP segments.
 * MVP points total 14 per raid.
 */
@Getter
@RequiredArgsConstructor
public enum Segment
{
	MAIDEN("Maiden", 0, 2),
	BLOAT("Bloat", 1, 2),
	NYLOCAS("Nylocas", 2, 1),
	SOTETSEG("Sotetseg", 3, 1),
	XARPUS("Xarpus", 4, 2),
	VERZIK_P1("Verzik P1", 5, 2),
	VERZIK_P2("Verzik P2", 5, 2),
	VERZIK_P3("Verzik P3", 5, 2);

	public static final int ROOM_COUNT = 6;
	public static final int POINTS_PER_ROOM = 3;
	public static final int DEATH_PENALTY = 4;
	public static final int TOTAL_MVP_POINTS = 14;
	public static final int MAX_PLAYER_POINTS = ROOM_COUNT * POINTS_PER_ROOM + TOTAL_MVP_POINTS;

	private static final Segment[] VALUES = values();

	private final String displayName;
	private final int room;
	private final int mvpPoints;

	/**
	 * Whether completing this segment completes its room (and so awards room points).
	 */
	public boolean endsRoom()
	{
		return ordinal() == VALUES.length - 1 || VALUES[ordinal() + 1].room != room;
	}

	public static int count()
	{
		return VALUES.length;
	}
}

package com.camjewell.tobpointtracker;

import com.google.gson.annotations.SerializedName;
import lombok.EqualsAndHashCode;
import lombok.Value;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Broadcast to the RuneLite party after each segment so teammates can work out who earned each MVP. It carries the
 * sender's full per-segment boss damage for the raid, so a missed message is fixed by the next one.
 */
@Value
@EqualsAndHashCode(callSuper = true)
public class ToBDamageUpdate extends PartyMemberMessage
{
	/**
	 * In-game name of the sender, used to match them to a ToB party slot.
	 */
	@SerializedName("n")
	String name;
	/**
	 * Boss damage per {@link Segment}, indexed by ordinal.
	 */
	@SerializedName("d")
	int[] damage;
}

package com.camjewell.tobpointtracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ToBPointTrackerConfig.GROUP)
public interface ToBPointTrackerConfig extends Config
{
	String GROUP = "tobpointtracker";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Show deaths and purple chances while in the Theatre of Blood",
		position = 0
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPlayers",
		name = "Display teammates",
		description = "Display the purple chance of teammates who share their damage through your RuneLite party with this"
			+ " plugin. Players with deaths are shown in red",
		position = 1
	)
	default boolean showPlayers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "uniqueChance",
		name = "Display the chance of a unique",
		description = "Display your personal purple chance, the team's, or both. Your chance is a range while some of your"
			+ " MVP points can't be proven because teammates aren't sharing their damage",
		position = 2
	)
	default UniqueChanceDisplay uniqueChance()
	{
		return UniqueChanceDisplay.BOTH;
	}

	@ConfigItem(
		keyName = "chanceBasis",
		name = "Unique chance basis",
		description = "Projected: starts at the full chance and only drops when someone dies, assuming the rest of the raid"
			+ " is cleared without dying. Current: starts at 0% and climbs as rooms are completed, like the CoX and ToA"
			+ " trackers. Both end at the same value once Verzik is dead.",
		position = 3
	)
	default ChanceBasis chanceBasis()
	{
		return ChanceBasis.PROJECTED;
	}

	@ConfigItem(
		keyName = "shareDamage",
		name = "Share with party",
		description = "Send your boss damage to your RuneLite party so teammates running this plugin can work out MVP points."
			+ " Without everyone sharing, your chance may be a range rather than exact.",
		position = 4
	)
	default boolean shareDamage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatSummary",
		name = "Raid summary in chat",
		description = "Post deaths and purple chances to the chatbox when Verzik dies",
		position = 5
	)
	default boolean chatSummary()
	{
		return true;
	}
}

package com.camjewell.tobpointtracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.text.DecimalFormat;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

/**
 * Laid out like the Raid Points Overlay plugin's CoX overlay, but showing what actually changes a ToB unique chance:
 * deaths, your purple chance, and the team's. Point breakdowns are on hover.
 * <p>
 * Your chance is a range when MVP points can't be proven without teammates' damage, and an exact value otherwise.
 * Teammates only get their own line when they share damage through the party.
 */
class ToBPointTrackerOverlay extends OverlayPanel
{
	private static final DecimalFormat CHANCE_FORMAT = new DecimalFormat("#0.00%");
	private static final DecimalFormat CHANCE_RANGE_LOW_FORMAT = new DecimalFormat("#0.00");

	private static final Color DEATH_COLOR = Color.RED;
	private static final Color WON_COLOR = Color.GREEN;
	private static final Color UNKNOWN_COLOR = Color.LIGHT_GRAY;
	private static final Color HEADER_COLOR = ColorScheme.BRAND_ORANGE;

	private static final String BR = "</br>";
	private static final String INDENT = "    ";

	private final Client client;
	private final ToBPointTrackerPlugin plugin;
	private final ToBPointTrackerConfig config;
	private final TooltipManager tooltipManager;

	@Inject
	private ToBPointTrackerOverlay(Client client, ToBPointTrackerPlugin plugin, ToBPointTrackerConfig config,
		TooltipManager tooltipManager)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.TOP_RIGHT);
		setPriority(Overlay.PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || !plugin.isInRaid())
		{
			return null;
		}

		PointCalculator.RaidScore score = plugin.getScore();
		if (score == null)
		{
			return null;
		}

		// Deaths are the only thing that lowers the team's final points
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Deaths:")
			.right(String.valueOf(score.getTotalDeaths()))
			.rightColor(score.getTotalDeaths() > 0 ? DEATH_COLOR : Color.WHITE)
			.build());

		UniqueChanceDisplay display = config.uniqueChance();
		boolean canRoll = score.getMode().canRollUniques();

		if (canRoll && (display == UniqueChanceDisplay.PERSONAL_CHANCE || display == UniqueChanceDisplay.BOTH))
		{
			for (PointCalculator.PlayerScore p : score.getPlayers())
			{
				if (p.isLocal())
				{
					addPlayerLine(p);
				}
			}
			if (config.showPlayers())
			{
				for (PointCalculator.PlayerScore p : score.getPlayers())
				{
					if (!p.isLocal() && p.isDamageKnown())
					{
						addPlayerLine(p);
					}
				}
			}
		}

		if (display == UniqueChanceDisplay.TEAM_CHANCE || display == UniqueChanceDisplay.BOTH)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Team:")
				.right(canRoll ? CHANCE_FORMAT.format(score.getTeamUniqueChance()) : "N/A (Entry)")
				.build());
		}

		Dimension dimension = super.render(graphics);
		addTooltip(score);
		return dimension;
	}

	private void addPlayerLine(PointCalculator.PlayerScore p)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(p.getName() + ":")
			.right(formatChance(p))
			.rightColor(p.getDeaths() > 0 ? DEATH_COLOR : Color.WHITE)
			.build());
	}

	/**
	 * A player's chance as an exact value, or "low-high%" while some of their MVP points can't be proven.
	 */
	static String formatChance(PointCalculator.PlayerScore p)
	{
		if (p.isExact())
		{
			return CHANCE_FORMAT.format(p.getMinUniqueChance());
		}
		return CHANCE_RANGE_LOW_FORMAT.format(p.getMinUniqueChance() * 100) + "-"
			+ CHANCE_FORMAT.format(p.getMaxUniqueChance());
	}

	private void addTooltip(PointCalculator.RaidScore score)
	{
		Rectangle bounds = getBounds();
		Point mouse = client.getMouseCanvasPosition();
		if (bounds == null || mouse == null || !bounds.contains(mouse.getX(), mouse.getY()))
		{
			return;
		}

		StringBuilder sb = new StringBuilder();
		header(sb, String.format("%s Mode, %d players", score.getMode().getDisplayName(), score.getTeamSize()));
		sb.append(BR).append(String.format("Team points: %d / %d", score.getTeamPoints(), score.getMaxPoints()));
		if (!score.isComplete() && score.getTotalDeaths() > 0)
		{
			sb.append(BR).append(detail(String.format("%d / %d if no one else dies",
				score.getProjectedTeamPoints(), score.getMaxPoints())));
		}

		sb.append(BR).append(BR);
		header(sb, "Player points");
		for (PointCalculator.PlayerScore p : score.getPlayers())
		{
			appendPlayerPoints(sb, p);
		}

		for (PointCalculator.PlayerScore p : score.getPlayers())
		{
			if (p.isLocal() && score.getMode().canRollUniques())
			{
				appendMvpOutcomes(sb, p);
			}
		}

		tooltipManager.add(new Tooltip(sb.toString()));
	}

	private static void header(StringBuilder sb, String text)
	{
		sb.append(ColorUtil.wrapWithColorTag(text, HEADER_COLOR));
	}

	private static String detail(String text)
	{
		return ColorUtil.wrapWithColorTag(INDENT + text, UNKNOWN_COLOR);
	}

	/**
	 * e.g.
	 * <pre>
	 * ThePrestiGIM: 16-20
	 *     18 rooms + 2-6 MVP - 4 for 1 death
	 * </pre>
	 */
	private static void appendPlayerPoints(StringBuilder sb, PointCalculator.PlayerScore p)
	{
		String points = p.isExact() ? String.valueOf(p.getMinPoints()) : p.getMinPoints() + "-" + p.getMaxPoints();
		sb.append(BR).append(p.getName()).append(": ")
			.append(ColorUtil.wrapWithColorTag(points, p.getDeaths() > 0 ? DEATH_COLOR : Color.WHITE));
		if (!p.isDamageKnown())
		{
			sb.append(ColorUtil.wrapWithColorTag(" (no plugin)", UNKNOWN_COLOR));
		}

		StringBuilder breakdown = new StringBuilder()
			.append(p.getRoomPoints()).append(" rooms + ");
		if (p.getMvpUnknown() > 0)
		{
			breakdown.append(p.getMvpWon()).append("-").append(p.getMvpWon() + p.getMvpUnknown());
		}
		else
		{
			breakdown.append(p.getMvpWon());
		}
		breakdown.append(" MVP");
		if (p.getDeaths() > 0)
		{
			breakdown.append(String.format(" - %d for %d death%s",
				p.getDeaths() * Segment.DEATH_PENALTY, p.getDeaths(), p.getDeaths() == 1 ? "" : "s"));
		}
		sb.append(BR).append(detail(breakdown.toString()));
	}

	/**
	 * Lists completed segments grouped by whether you provably won, provably lost, or can't tell their MVP points.
	 */
	private static void appendMvpOutcomes(StringBuilder sb, PointCalculator.PlayerScore p)
	{
		StringBuilder won = new StringBuilder();
		StringBuilder lost = new StringBuilder();
		StringBuilder unknown = new StringBuilder();
		for (Segment segment : Segment.values())
		{
			MvpOutcome outcome = p.getOutcomes()[segment.ordinal()];
			if (outcome == null)
			{
				continue;
			}

			StringBuilder list = outcome == MvpOutcome.WON ? won : outcome == MvpOutcome.LOST ? lost : unknown;
			if (list.length() > 0)
			{
				list.append(", ");
			}
			list.append(segment.getDisplayName()).append(" (").append(segment.getMvpPoints()).append(")");
		}

		if (won.length() + lost.length() + unknown.length() == 0)
		{
			return;
		}

		sb.append(BR).append(BR);
		header(sb, "Your MVPs");
		appendOutcomeLine(sb, "Won", won, WON_COLOR);
		appendOutcomeLine(sb, "Lost", lost, DEATH_COLOR);
		appendOutcomeLine(sb, "Unknown", unknown, UNKNOWN_COLOR);
	}

	private static void appendOutcomeLine(StringBuilder sb, String label, StringBuilder segments, Color color)
	{
		if (segments.length() > 0)
		{
			sb.append(BR).append(ColorUtil.wrapWithColorTag(label + ": ", color)).append(segments);
		}
	}
}

package com.camjewell.tobpointtracker;

import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "ToB Point Tracker",
	description = "Tracks individual and team Theatre of Blood points and your purple (unique) chance",
	tags = {"tob", "theatre", "blood", "raid", "points", "purple", "unique", "mvp"}
)
public class ToBPointTrackerPlugin extends Plugin
{
	// TOB_CLIENT_PARTYSTATUS: 0 = no party, 1 = in a party, 2 = inside the raid, 3 = dead and spectating
	private static final int STATUS_INSIDE = 2;
	private static final int STATUS_SPECTATING = 3;

	// TOB_CLIENT_P0-P4 party orb values: 0 = empty slot, 1-27 = scaled health, 30 = dead
	private static final int ORB_MAX_ALIVE = 27;
	private static final int ORB_DEAD = 30;

	private static final int[] NAME_VARCS = {
		VarClientID.TOB_CLIENT_NAME0, VarClientID.TOB_CLIENT_NAME1, VarClientID.TOB_CLIENT_NAME2,
		VarClientID.TOB_CLIENT_NAME3, VarClientID.TOB_CLIENT_NAME4,
	};
	private static final int[] ORB_VARBITS = {
		VarbitID.TOB_CLIENT_P0, VarbitID.TOB_CLIENT_P1, VarbitID.TOB_CLIENT_P2,
		VarbitID.TOB_CLIENT_P3, VarbitID.TOB_CLIENT_P4,
	};

	// e.g. "Wave 'The Maiden of Sugadinti' (Normal Mode) complete!<br>Duration: 2:05.40"
	private static final Pattern WAVE_COMPLETE = Pattern.compile("Wave '(.+?)' \\((\\w+) Mode\\) complete!");

	// Give hitsplats landing on the killing tick a moment before sharing damage
	private static final int SHARE_DELAY_TICKS = 2;
	// Give teammates' final damage updates time to arrive before summarising
	private static final int SUMMARY_DELAY_TICKS = 5;
	// A relog this soon after leaving resumes the raid instead of starting a new one
	private static final Duration RESUME_WINDOW = Duration.ofMinutes(10);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ToBPointTrackerConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ToBPointTrackerOverlay overlay;

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	@Inject
	private ChatMessageManager chatMessageManager;

	private RaidState raid;
	private PointCalculator.RaidScore score;
	private boolean inRaid;
	private boolean leftViaLogout;
	private Instant leftRaidAt;
	private final int[] previousOrbs = new int[ORB_VARBITS.length];
	private int shareTicks = -1;
	private int summaryTicks = -1;

	@Provides
	ToBPointTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ToBPointTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		wsClient.registerMessage(ToBDamageUpdate.class);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		wsClient.unregisterMessage(ToBDamageUpdate.class);
		raid = null;
		score = null;
		inRaid = false;
		shareTicks = -1;
		summaryTicks = -1;
	}

	boolean isInRaid()
	{
		return inRaid && raid != null;
	}

	/**
	 * The latest score for the current raid, or null outside of one. Called from the overlay on the client thread.
	 */
	PointCalculator.RaidScore getScore()
	{
		if (raid == null)
		{
			return null;
		}
		if (score == null)
		{
			score = PointCalculator.calculate(raid, config.chanceBasis());
		}
		return score;
	}

	private void invalidate()
	{
		score = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ToBPointTrackerConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invokeLater(this::invalidate);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
			case CONNECTION_LOST:
				if (inRaid)
				{
					leaveRaid(true);
				}
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int status = client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS);
		boolean nowInRaid = status == STATUS_INSIDE || status == STATUS_SPECTATING;
		if (nowInRaid && !inRaid)
		{
			enterRaid();
		}
		else if (!nowInRaid && inRaid)
		{
			leaveRaid(false);
		}

		if (!isInRaid())
		{
			return;
		}

		updateTeam();
		checkOrbs();

		if (shareTicks >= 0 && shareTicks-- == 0)
		{
			shareDamage();
		}
		if (summaryTicks >= 0 && summaryTicks-- == 0)
		{
			postSummary();
		}
	}

	private void enterRaid()
	{
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return;
		}

		String localKey = Text.standardize(local.getName());
		boolean resume = raid != null
			&& !raid.isComplete()
			&& leftViaLogout
			&& leftRaidAt != null
			&& Duration.between(leftRaidAt, Instant.now()).compareTo(RESUME_WINDOW) < 0
			&& raid.getLocalName().equals(localKey);

		if (!resume)
		{
			log.debug("Starting new ToB raid tracking");
			raid = new RaidState(localKey);
			invalidate();
		}

		inRaid = true;
		// Don't treat orbs that are already dead when we (re)join as fresh deaths
		for (int i = 0; i < ORB_VARBITS.length; i++)
		{
			previousOrbs[i] = client.getVarbitValue(ORB_VARBITS[i]);
		}
	}

	private void leaveRaid(boolean viaLogout)
	{
		inRaid = false;
		leftViaLogout = viaLogout;
		leftRaidAt = Instant.now();
		shareTicks = -1;
		summaryTicks = -1;
	}

	private void updateTeam()
	{
		int before = raid.getTeam().size();
		for (int varc : NAME_VARCS)
		{
			String name = cleanName(client.getVarcStrValue(varc));
			if (!name.isEmpty())
			{
				raid.addTeamMember(Text.standardize(name), name);
			}
		}
		if (raid.getTeam().size() != before)
		{
			invalidate();
		}
	}

	/**
	 * Backup death detection for players we can't see die, using the party health orbs.
	 */
	private void checkOrbs()
	{
		for (int i = 0; i < ORB_VARBITS.length; i++)
		{
			int orb = client.getVarbitValue(ORB_VARBITS[i]);
			int previous = previousOrbs[i];
			previousOrbs[i] = orb;

			boolean alive = orb > 0 && orb <= ORB_MAX_ALIVE;
			boolean wasAlive = previous > 0 && previous <= ORB_MAX_ALIVE;
			if (orb == ORB_DEAD && wasAlive || alive && previous == ORB_DEAD)
			{
				String name = cleanName(client.getVarcStrValue(NAME_VARCS[i]));
				if (name.isEmpty())
				{
					continue;
				}

				if (alive)
				{
					// Respawned for the next room
					raid.markAlive(Text.standardize(name));
				}
				else
				{
					recordDeath(name);
				}
			}
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!isInRaid())
		{
			return;
		}

		Actor actor = event.getActor();
		if (actor instanceof Player && actor.getName() != null)
		{
			recordDeath(actor.getName());
		}
		else if (actor instanceof NPC)
		{
			Segment segment = TobNpcs.bossSegment(((NPC) actor).getId());
			if (segment != null)
			{
				completeSegment(segment);
			}
		}
	}

	private void recordDeath(String name)
	{
		if (raid.recordDeath(Text.standardize(name)))
		{
			log.debug("{} died in room {}", name, raid.getCurrentRoom());
			invalidate();
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		onNpc(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		onNpc(event.getNpc());
	}

	private void onNpc(NPC npc)
	{
		if (!isInRaid())
		{
			return;
		}

		int id = npc.getId();
		RaidMode mode = TobNpcs.modeOf(id);
		if (mode != null && !raid.isModeKnown())
		{
			raid.setMode(mode);
			raid.setModeKnown(true);
			invalidate();
		}

		Segment ended = TobNpcs.endedSegment(id);
		if (ended != null)
		{
			completeSegment(ended);
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!isInRaid() || !(event.getActor() instanceof NPC))
		{
			return;
		}

		Segment segment = TobNpcs.bossSegment(((NPC) event.getActor()).getId());
		if (segment == null || raid.getCompleted().contains(segment))
		{
			return;
		}

		Hitsplat hitsplat = event.getHitsplat();
		boolean mine = hitsplat.isMine();
		if (mine || hitsplat.isOthers())
		{
			raid.recordHit(segment, hitsplat.getAmount(), mine);
			invalidate();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!isInRaid() || event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		Matcher m = WAVE_COMPLETE.matcher(Text.removeTags(event.getMessage()));
		if (!m.find())
		{
			return;
		}

		RaidMode mode = RaidMode.fromChatName(m.group(2));
		if (!raid.isModeKnown() || raid.getMode() != mode)
		{
			raid.setMode(mode);
			raid.setModeKnown(true);
			invalidate();
		}

		Segment segment = segmentForWave(m.group(1));
		if (segment != null)
		{
			completeSegment(segment);
		}
	}

	private static Segment segmentForWave(String wave)
	{
		String w = wave.toLowerCase(Locale.ROOT);
		if (w.contains("maiden"))
		{
			return Segment.MAIDEN;
		}
		if (w.contains("bloat"))
		{
			return Segment.BLOAT;
		}
		if (w.contains("nylocas"))
		{
			return Segment.NYLOCAS;
		}
		if (w.contains("sotetseg"))
		{
			return Segment.SOTETSEG;
		}
		if (w.contains("xarpus"))
		{
			return Segment.XARPUS;
		}
		if (w.contains("verzik") || w.contains("final"))
		{
			return Segment.VERZIK_P3;
		}
		return null;
	}

	private void completeSegment(Segment segment)
	{
		if (!raid.completeThrough(segment))
		{
			return;
		}

		log.debug("Completed {}", segment);
		invalidate();
		shareTicks = SHARE_DELAY_TICKS;
		if (raid.isComplete())
		{
			summaryTicks = SUMMARY_DELAY_TICKS;
		}
	}

	private void shareDamage()
	{
		if (!config.shareDamage() || !partyService.isInParty() || !raid.getTeam().containsKey(raid.getLocalName()))
		{
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return;
		}

		partyService.send(new ToBDamageUpdate(local.getName(), raid.getLocalDamage().clone()));
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		// Teammates in the new party will resend their full damage after the next segment
		clientThread.invokeLater(() ->
		{
			if (raid != null)
			{
				raid.clearPartyDamage();
				invalidate();
			}
		});
	}

	@Subscribe
	public void onToBDamageUpdate(ToBDamageUpdate update)
	{
		// Party messages arrive on the websocket thread
		clientThread.invokeLater(() ->
		{
			if (raid == null || update.getName() == null)
			{
				return;
			}

			raid.setPartyDamage(Text.standardize(update.getName()), update.getDamage());
			invalidate();
		});
	}

	private void postSummary()
	{
		if (!config.chatSummary())
		{
			return;
		}

		PointCalculator.RaidScore s = getScore();
		ChatMessageBuilder message = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("ToB")
			.append(ChatColorType.NORMAL)
			.append(String.format(" (%s, %d-man, %d death%s): ", s.getMode().getDisplayName(), s.getTeamSize(),
				s.getTotalDeaths(), s.getTotalDeaths() == 1 ? "" : "s"));

		if (s.getMode().canRollUniques())
		{
			message.append("purple chance ")
				.append(ChatColorType.HIGHLIGHT)
				.append(formatPercent(s.getTeamUniqueChance()))
				.append(ChatColorType.NORMAL)
				.append(" team");
			for (PointCalculator.PlayerScore p : s.getPlayers())
			{
				if (p.isLocal())
				{
					message.append(", ")
						.append(ChatColorType.HIGHLIGHT)
						.append(ToBPointTrackerOverlay.formatChance(p))
						.append(ChatColorType.NORMAL)
						.append(" you");
					if (!p.isExact())
					{
						message.append(String.format(" (%d MVP points unproven)", p.getMvpUnknown()));
					}
				}
			}
		}
		else
		{
			message.append("Entry Mode can't roll purples");
		}

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message.append(".").build())
			.build());
	}

	static String formatPercent(double fraction)
	{
		return String.format("%.2f%%", fraction * 100);
	}

	private static String cleanName(String name)
	{
		if (name == null)
		{
			return "";
		}
		return Text.removeTags(name).replace(' ', ' ').trim();
	}
}

package com.camjewell.tobpointtracker;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.NpcID;

/**
 * Maps ToB boss NPC ids (in all three modes) to the scoring segment damage on them counts towards.
 */
final class TobNpcs
{
	private TobNpcs()
	{
	}

	private static final Map<Integer, Segment> BOSS_SEGMENTS = ImmutableMap.<Integer, Segment>builder()
		// Maiden
		.put(NpcID.TOB_MAIDEN_100, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_70, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_50, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_30, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_100_STORY, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_70_STORY, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_50_STORY, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_30_STORY, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_100_HARD, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_70_HARD, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_50_HARD, Segment.MAIDEN)
		.put(NpcID.TOB_MAIDEN_30_HARD, Segment.MAIDEN)
		// Bloat
		.put(NpcID.TOB_BLOAT, Segment.BLOAT)
		.put(NpcID.TOB_BLOAT_STORY, Segment.BLOAT)
		.put(NpcID.TOB_BLOAT_HARD, Segment.BLOAT)
		// Nylocas Vasilias
		.put(NpcID.NYLOCAS_BOSS_MELEE, Segment.NYLOCAS)
		.put(NpcID.NYLOCAS_BOSS_MAGIC, Segment.NYLOCAS)
		.put(NpcID.NYLOCAS_BOSS_RANGED, Segment.NYLOCAS)
		.put(NpcID.NYLOCAS_BOSS_MELEE_STORY, Segment.NYLOCAS)
		.put(NpcID.NYLOCAS_BOSS_MAGIC_STORY, Segment.NYLOCAS)
		.put(NpcID.NYLOCAS_BOSS_RANGED_STORY, Segment.NYLOCAS)
		.put(NpcID.NYLOCAS_BOSS_MELEE_HARD, Segment.NYLOCAS)
		.put(NpcID.NYLOCAS_BOSS_MAGIC_HARD, Segment.NYLOCAS)
		.put(NpcID.NYLOCAS_BOSS_RANGED_HARD, Segment.NYLOCAS)
		// Sotetseg
