package com.camjewell.tobpointtracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PointCalculatorTest
{
	private static final double EPSILON = 1e-9;

	private static RaidState raid(String... names)
	{
		RaidState raid = new RaidState(names[0]);
		for (String name : names)
		{
			raid.addTeamMember(name, name);
		}
		return raid;
	}

	private static PointCalculator.PlayerScore player(PointCalculator.RaidScore score, String name)
	{
		return score.getPlayers().stream().filter(p -> p.getName().equals(name)).findFirst().orElseThrow(AssertionError::new);
	}

	@Test
	public void maxPointsScaleWithTeamSize()
	{
		assertEquals(32, PointCalculator.maxTeamPoints(1));
		assertEquals(50, PointCalculator.maxTeamPoints(2));
		assertEquals(68, PointCalculator.maxTeamPoints(3));
		assertEquals(86, PointCalculator.maxTeamPoints(4));
		assertEquals(104, PointCalculator.maxTeamPoints(5));
		assertEquals(32, Segment.MAX_PLAYER_POINTS);
	}

	@Test
	public void mvpPointsTotalFourteenAcrossSixRooms()
	{
		int mvp = 0;
		int rooms = 0;
		for (Segment s : Segment.values())
		{
			mvp += s.getMvpPoints();
			rooms += s.endsRoom() ? 1 : 0;
		}
		assertEquals(14, mvp);
		assertEquals(6, rooms);
	}

	@Test
	public void soloDeathlessRaidIsPerfect()
	{
		RaidState raid = raid("me");
		raid.recordHit(Segment.MAIDEN, 100, true);
		for (Segment s : Segment.values())
		{
			raid.recordHit(s, 10, true);
		}
		raid.completeThrough(Segment.VERZIK_P3);

		PointCalculator.RaidScore score = PointCalculator.calculate(raid);
		assertTrue(score.isComplete());
		assertEquals(32, score.getTeamPoints());
		assertEquals(32, player(score, "me").getMinPoints());
		assertTrue(player(score, "me").isExact());
		assertEquals(1 / 9.1, score.getTeamUniqueChance(), EPSILON);
		assertEquals(1 / 9.1, player(score, "me").getMinUniqueChance(), EPSILON);
	}

	@Test
	public void deathsCostFourPointsAndReduceTeamChance()
	{
		RaidState raid = raid("me", "a", "b", "c");
		raid.setMode(RaidMode.HARD);
		raid.recordDeath("a");
		raid.recordDeath("a"); // same room, can't die twice
		raid.completeThrough(Segment.MAIDEN);
		raid.markAlive("a"); // respawned for Bloat
		raid.recordDeath("a");

		PointCalculator.RaidScore score = PointCalculator.calculate(raid);
		assertEquals(2, score.getTotalDeaths());
		assertEquals(86 - 8, score.getProjectedTeamPoints());
		assertEquals((1 / 7.7) * 78 / 86, score.getTeamUniqueChance(), EPSILON);
		// 3 room points - 8, floored at 0
		assertEquals(0, player(score, "a").getMaxPoints());
	}

	@Test
	public void lateDuplicateDeathAcrossRoomEndIsIgnored()
	{
		RaidState raid = raid("me", "a");
		// ActorDeath during Verzik P3, then the party orb catches up just after Verzik dies
		raid.completeThrough(Segment.VERZIK_P2);
		assertTrue(raid.recordDeath("a"));
		raid.completeThrough(Segment.VERZIK_P3);
		assertFalse(raid.recordDeath("a"));

		// Same lag across an ordinary room change
		raid = raid("me", "a");
		assertTrue(raid.recordDeath("a"));
		raid.completeThrough(Segment.MAIDEN);
		assertFalse(raid.recordDeath("a"));

		// Once they respawn, they can die again
		raid.markAlive("a");
		assertTrue(raid.recordDeath("a"));
		assertEquals(2, raid.getDeaths("a"));
	}

	@Test
	public void currentChanceClimbsWhileProjectedOnlyDropsOnDeaths()
	{
		RaidState raid = raid("me", "a");
		assertEquals(0, PointCalculator.calculate(raid, ChanceBasis.CURRENT).getTeamUniqueChance(), EPSILON);
		assertEquals(1 / 9.1, PointCalculator.calculate(raid, ChanceBasis.PROJECTED).getTeamUniqueChance(), EPSILON);

		raid.completeThrough(Segment.MAIDEN);
		// 2 players * 3 room points + 2 MVP
		assertEquals((1 / 9.1) * 8 / 50, PointCalculator.calculate(raid, ChanceBasis.CURRENT).getTeamUniqueChance(), EPSILON);
		assertEquals(1 / 9.1, PointCalculator.calculate(raid, ChanceBasis.PROJECTED).getTeamUniqueChance(), EPSILON);

		raid.recordDeath("a");
		raid.completeThrough(Segment.VERZIK_P3);
		double finished = (1 / 9.1) * 46 / 50;
		assertEquals(finished, PointCalculator.calculate(raid, ChanceBasis.CURRENT).getTeamUniqueChance(), EPSILON);
		assertEquals(finished, PointCalculator.calculate(raid, ChanceBasis.PROJECTED).getTeamUniqueChance(), EPSILON);
	}

	@Test
	public void entryModeCannotRollUniques()
	{
		RaidState raid = raid("me", "a");
		raid.setMode(RaidMode.ENTRY);
		raid.completeThrough(Segment.VERZIK_P3);

		PointCalculator.RaidScore score = PointCalculator.calculate(raid);
		assertEquals(50, score.getTeamPoints());
		assertEquals(0, score.getTeamUniqueChance(), EPSILON);
		assertFalse(RaidMode.ENTRY.canRollUniques());
	}

	@Test
	public void mvpGoesToTopDamagerWhenEveryoneSharesData()
	{
		RaidState raid = raid("me", "a");
		raid.recordHit(Segment.MAIDEN, 300, true);
		raid.recordHit(Segment.MAIDEN, 500, false);
		raid.setPartyDamage("a", damage(Segment.MAIDEN, 500));
		raid.completeThrough(Segment.MAIDEN);

		PointCalculator.RaidScore score = PointCalculator.calculate(raid);
		assertEquals(MvpOutcome.LOST, player(score, "me").getOutcomes()[Segment.MAIDEN.ordinal()]);
		assertEquals(MvpOutcome.WON, player(score, "a").getOutcomes()[Segment.MAIDEN.ordinal()]);
		assertTrue(player(score, "me").isExact());
		assertEquals(3, player(score, "me").getMinPoints());
		assertEquals(5, player(score, "a").getMinPoints());
		assertEquals(8, score.getTeamPoints());
	}

	@Test
	public void mvpIsUnknownWhenTeammatesWithoutDataMightHaveWon()
	{
		RaidState raid = raid("me", "a", "b");
		raid.recordHit(Segment.MAIDEN, 400, true);
		raid.recordHit(Segment.MAIDEN, 600, false); // a and b combined, split unknown
		raid.completeThrough(Segment.MAIDEN);

		PointCalculator.RaidScore score = PointCalculator.calculate(raid);
		PointCalculator.PlayerScore me = player(score, "me");
		assertEquals(MvpOutcome.UNKNOWN, me.getOutcomes()[Segment.MAIDEN.ordinal()]);
		assertFalse(me.isExact());
		assertEquals(3, me.getMinPoints());
		assertEquals(5, me.getMaxPoints());
		// Team total is still exact: MVP points are always awarded to someone
		assertEquals(3 * 3 + 2, score.getTeamPoints());
		double teamChance = score.getTeamUniqueChance();
		assertEquals(teamChance * 3 / 11, me.getMinUniqueChance(), EPSILON);
		assertEquals(teamChance * 5 / 11, me.getMaxUniqueChance(), EPSILON);
	}

	@Test
	public void mvpIsProvablyWonWhenWeOutdamageEverythingElse()
	{
		RaidState raid = raid("me", "a", "b");
		raid.recordHit(Segment.MAIDEN, 700, true);
		raid.recordHit(Segment.MAIDEN, 600, false);
		raid.completeThrough(Segment.MAIDEN);

		PointCalculator.RaidScore score = PointCalculator.calculate(raid);
		assertEquals(MvpOutcome.WON, player(score, "me").getOutcomes()[Segment.MAIDEN.ordinal()]);
		assertTrue(player(score, "me").isExact());
		assertEquals(5, player(score, "me").getMinPoints());
		// Teammates without data provably lost, but their own points still can't be known
		assertEquals(MvpOutcome.LOST, player(score, "a").getOutcomes()[Segment.MAIDEN.ordinal()]);
	}

	@Test
	public void mvpIsProvablyLostWhenSomeTeammateMustHaveOutdamagedUs()
	{
		RaidState raid = raid("me", "a", "b");
		raid.recordHit(Segment.MAIDEN, 200, true);
		raid.recordHit(Segment.MAIDEN, 500, false); // more than 2 * 200, so a or b dealt over 200
		raid.completeThrough(Segment.MAIDEN);

		PointCalculator.PlayerScore me = player(PointCalculator.calculate(raid), "me");
		assertEquals(MvpOutcome.LOST, me.getOutcomes()[Segment.MAIDEN.ordinal()]);
		assertTrue(me.isExact());
		assertEquals(3, me.getMinPoints());
	}

	@Test
	public void tiesAreUnknown()
	{
		RaidState raid = raid("me", "a");
		raid.recordHit(Segment.BLOAT, 300, true);
		raid.setPartyDamage("a", damage(Segment.BLOAT, 300));
		raid.completeThrough(Segment.BLOAT);

		PointCalculator.RaidScore score = PointCalculator.calculate(raid);
		assertEquals(MvpOutcome.UNKNOWN, player(score, "me").getOutcomes()[Segment.BLOAT.ordinal()]);
		assertEquals(MvpOutcome.UNKNOWN, player(score, "a").getOutcomes()[Segment.BLOAT.ordinal()]);
	}

	@Test
	public void personalChanceIsShareOfTeamChance()
	{
		RaidState raid = raid("me", "a");
		raid.setPartyDamage("a", damage(Segment.MAIDEN, 0));
		for (Segment s : Segment.values())
		{
			raid.recordHit(s, 100, true);
		}
		raid.completeThrough(Segment.VERZIK_P3);

		PointCalculator.RaidScore score = PointCalculator.calculate(raid);
		assertEquals(50, score.getTeamPoints());
		assertEquals(32, player(score, "me").getMinPoints());
		assertEquals(18, player(score, "a").getMinPoints());
		assertEquals((1 / 9.1) * 32 / 50, player(score, "me").getMinUniqueChance(), EPSILON);
		assertEquals((1 / 9.1) * 32 / 50, player(score, "me").getMaxUniqueChance(), EPSILON);
	}

	@Test
	public void chanceFormatsAsRangeOnlyWhenUnproven()
	{
		RaidState raid = raid("me", "a", "b");
		raid.recordHit(Segment.MAIDEN, 400, true);
		raid.recordHit(Segment.MAIDEN, 600, false);
		raid.completeThrough(Segment.MAIDEN);
		assertTrue(ToBPointTrackerOverlay.formatChance(player(PointCalculator.calculate(raid), "me")).matches("\\d+\\.\\d\\d-\\d+\\.\\d\\d%"));

		RaidState solo = raid("me");
		solo.recordHit(Segment.MAIDEN, 400, true);
		solo.completeThrough(Segment.MAIDEN);
		assertEquals("10.99%", ToBPointTrackerOverlay.formatChance(player(PointCalculator.calculate(solo), "me")));
	}

	@Test
	public void completingLaterSegmentBackfillsEarlierOnes()
	{
		RaidState raid = raid("me");
		raid.completeThrough(Segment.SOTETSEG);
		assertEquals(4, raid.getRoomsCompleted());
		assertEquals(4, raid.getCurrentRoom());
		raid.completeThrough(Segment.VERZIK_P1);
		assertEquals(5, raid.getRoomsCompleted());
		assertEquals(Segment.VERZIK_P2, raid.getCurrentSegment());
	}

	private static int[] damage(Segment segment, int amount)
	{
		int[] d = new int[Segment.count()];
		d[segment.ordinal()] = amount;
		return d;
	}
}

